def build_snapshot_list_type_adapter(
    state_t: type[StateT], run_end_t: type[RunEndT]
) -> pydantic.TypeAdapter[list[Snapshot[StateT, RunEndT]]]:
    """Build a type adapter for a list of snapshots.

    This method should be called from within
    [`set_types`][pydantic_graph.persistence.BaseStatePersistence.set_types]
    where context variables will be set such that Pydantic can create a schema for
    [`NodeSnapshot.node`][pydantic_graph.persistence.NodeSnapshot.node].
    """
    return pydantic.TypeAdapter(list[Annotated[Snapshot[state_t, run_end_t], pydantic.Discriminator('kind')]])

class CustomNodeSchema:
    def __get_pydantic_core_schema__(
        self, _source_type: Any, handler: pydantic.GetCoreSchemaHandler
    ) -> core_schema.CoreSchema:
        try:
            nodes = nodes_type_context.get()
        except LookupError as e:
            raise RuntimeError(
                'Unable to build a Pydantic schema for `BaseNode` without setting `nodes_type_context`. '
                'You should build Pydantic schemas for snapshots using `StatePersistence.set_types()`.'
            ) from e
        if len(nodes) == 1:
            nodes_type = nodes[0]
        else:
            nodes_annotated = [Annotated[node, pydantic.Tag(node.get_node_id())] for node in nodes]
            nodes_type = Annotated[Union[tuple(nodes_annotated)], pydantic.Discriminator(self._node_discriminator)]  # noqa: UP007

        schema = handler(nodes_type)
        schema['serialization'] = core_schema.wrap_serializer_function_ser_schema(
            function=self._node_serializer,
            return_schema=core_schema.dict_schema(core_schema.str_schema(), core_schema.any_schema()),
        )
        return schema

    @staticmethod
    def _node_discriminator(node_data: Any) -> str:
        return node_data.get('node_id')

    @staticmethod
    def _node_serializer(node: Any, handler: pydantic.SerializerFunctionWrapHandler) -> dict[str, Any]:
        node_dict = handler(node)
        node_dict['node_id'] = node.get_node_id()
        return node_dict

def set_nodes_type_context(nodes: Sequence[type[BaseNode[Any, Any, Any]]]) -> Iterator[None]:
    token = nodes_type_context.set(nodes)
    try:
        yield
    finally:
        nodes_type_context.reset(token)

class FullStatePersistence(BaseStatePersistence[StateT, RunEndT]):
    """In memory state persistence that hold a list of snapshots."""

    deep_copy: bool = True
    """Whether to deep copy the state and nodes when storing them.

    Defaults to `True` so even if nodes or state are modified after the snapshot is taken,
    the persistence history will record the value at the time of the snapshot.
    """
    history: list[Snapshot[StateT, RunEndT]] = field(default_factory=list[Snapshot[StateT, RunEndT]])
    """List of snapshots taken during the graph run."""
    _snapshots_type_adapter: pydantic.TypeAdapter[list[Snapshot[StateT, RunEndT]]] | None = field(
        default=None, init=False, repr=False
    )

    async def snapshot_node(self, state: StateT, next_node: BaseNode[StateT, Any, RunEndT]) -> None:
        snapshot = NodeSnapshot(
            state=self._prep_state(state),
            node=next_node.deep_copy() if self.deep_copy else next_node,
        )
        self.history.append(snapshot)

    async def snapshot_node_if_new(
        self, snapshot_id: str, state: StateT, next_node: BaseNode[StateT, Any, RunEndT]
    ) -> None:
        if not any(s.id == snapshot_id for s in self.history):
            await self.snapshot_node(state, next_node)

    async def snapshot_end(self, state: StateT, end: End[RunEndT]) -> None:
        snapshot = EndSnapshot(
            state=self._prep_state(state),
            result=end.deep_copy_data() if self.deep_copy else end,
        )
        self.history.append(snapshot)

    @asynccontextmanager
    async def record_run(self, snapshot_id: str) -> AsyncIterator[None]:
        try:
            snapshot = next(s for s in self.history if s.id == snapshot_id)
        except StopIteration as e:
            raise LookupError(f'No snapshot found with id={snapshot_id!r}') from e

        assert isinstance(snapshot, NodeSnapshot), 'Only NodeSnapshot can be recorded'
        exceptions.GraphNodeStatusError.check(snapshot.status)
        snapshot.status = 'running'
        snapshot.start_ts = _utils.now_utc()
        start = perf_counter()
        try:
            yield
        except Exception:
            snapshot.duration = perf_counter() - start
            snapshot.status = 'error'
            raise
        else:
            snapshot.duration = perf_counter() - start
            snapshot.status = 'success'

    async def load_next(self) -> NodeSnapshot[StateT, RunEndT] | None:
        if snapshot := next((s for s in self.history if isinstance(s, NodeSnapshot) and s.status == 'created'), None):
            snapshot.status = 'pending'
            return copy.deepcopy(snapshot)

    async def load_all(self) -> list[Snapshot[StateT, RunEndT]]:
        return self.history

    def should_set_types(self) -> bool:
        return self._snapshots_type_adapter is None

    def set_types(self, state_type: type[StateT], run_end_type: type[RunEndT]) -> None:
        self._snapshots_type_adapter = build_snapshot_list_type_adapter(state_type, run_end_type)

    def dump_json(self, *, indent: int | None = None) -> bytes:
        """Dump the history to JSON bytes."""
        assert self._snapshots_type_adapter is not None, 'type adapter must be set to use `dump_json`'
        return self._snapshots_type_adapter.dump_json(self.history, indent=indent)

    def load_json(self, json_data: str | bytes | bytearray) -> None:
        """Load the history from JSON."""
        assert self._snapshots_type_adapter is not None, 'type adapter must be set to use `load_json`'
        self.history = self._snapshots_type_adapter.validate_json(json_data)

    def _prep_state(self, state: StateT) -> StateT:
        """Prepare state for snapshot, uses [`copy.deepcopy`][copy.deepcopy] by default."""
        if not self.deep_copy or state is None:
            return state
        else:
            return copy.deepcopy(state)

scripts.check_cassettes._sanitize_casset.source_code:
def _sanitize_cassette_name(name: str) -> str:
    """Replicate pytest-recording's cassette name sanitization."""
    for ch in _FORBIDDEN_CHARS:
        name = name.replace(ch, '-')
    return name

scripts.check_cassettes._has_vcr_marker.source_code:
def _has_vcr_marker(decorator_list: list[ast.expr]) -> bool:
    """Check if a decorator list contains pytest.mark.vcr (with or without parens)."""
    for dec in decorator_list:
        # @pytest.mark.vcr or @pytest.mark.vcr()
        if isinstance(dec, ast.Attribute) and dec.attr == 'vcr':
            return True
        if isinstance(dec, ast.Call) and isinstance(dec.func, ast.Attribute) and dec.func.attr == 'vcr':
            return True
    return False

scripts.check_cassettes._has_module_vcr_.source_code:
def _has_module_vcr_marker(tree: ast.Module) -> bool:
    """Check if the module has pytestmark = [..., pytest.mark.vcr, ...]."""
    for node in ast.iter_child_nodes(tree):
        if not isinstance(node, ast.Assign):
            continue
        for target in node.targets:
            if not (isinstance(target, ast.Name) and target.id == 'pytestmark'):
                continue
            return 'vcr' in ast.dump(node.value)
    return False

scripts.check_cassettes._collect_vcr_tes.source_code:
def _collect_vcr_tests_from_file(path: Path) -> set[str]:
    """Parse a Python test file and return cassette names for VCR-marked tests."""
    try:
        tree = ast.parse(path.read_text())
    except SyntaxError:
        return set()

    module_has_vcr = _has_module_vcr_marker(tree)
    cassette_names: set[str] = set()

    for node in ast.iter_child_nodes(tree):
        if isinstance(node, ast.FunctionDef | ast.AsyncFunctionDef):
            if not node.name.startswith('test_'):
                continue
            if module_has_vcr or _has_vcr_marker(node.decorator_list):
                # Parametrized tests get []  suffixes but cassettes use the base name
                cassette_names.add(_sanitize_cassette_name(node.name))

        elif isinstance(node, ast.ClassDef):
            class_has_vcr = _has_vcr_marker(node.decorator_list)
            for method in ast.iter_child_nodes(node):
                if not isinstance(method, ast.FunctionDef | ast.AsyncFunctionDef):
                    continue
                if not method.name.startswith('test_'):
                    continue
                if module_has_vcr or class_has_vcr or _has_vcr_marker(method.decorator_list):
                    cassette_names.add(_sanitize_cassette_name(f'{node.name}.{method.name}'))

    return cassette_names

scripts.check_cassettes.get_all_cassette.source_code:
def get_all_cassettes() -> dict[str, set[str]]:
    """Return {test_file_stem: set of cassette names (without .yaml)}."""
    cassettes: dict[str, set[str]] = {}

    for cassette_dir in Path('tests').rglob('cassettes'):
        if not cassette_dir.is_dir():
            continue
        for subdir in cassette_dir.iterdir():
            if subdir.is_dir():
                test_stem = subdir.name
                # Handle double extensions like .xai.yaml (xAI uses gRPC/protobuf, not HTTP)
                cassette_names = {f.stem[:-4] if f.stem.endswith('.xai') else f.stem for f in subdir.glob('*.yaml')}
                cassettes.setdefault(test_stem, set()).update(cassette_names)

    return cassettes

scripts.check_cassettes.get_all_tests.source_code:
def get_all_tests() -> dict[str, set[str]]:
    """Use AST parsing to find all VCR-marked tests and their cassette names."""
    tests: dict[str, set[str]] = defaultdict(set)

    for test_file in Path('tests').rglob('test_*.py'):
        cassette_names = _collect_vcr_tests_from_file(test_file)
        if cassette_names:
            tests[test_file.stem].update(cassette_names)

    return dict(tests)

scripts.upload_test_files.main.source_code:
async def main() -> None:
    providers = sys.argv[1:] if len(sys.argv) > 1 else ['openai', 'anthropic', 'xai', 'google', 'google-vertex', 'bedrock']

    for provider in providers:
        print(f'\n--- {provider} ---')
        if provider == 'openai':
            await upload_openai()
        elif provider == 'anthropic':
            await upload_anthropic()
        elif provider == 'xai':
            await upload_xai()
        elif provider == 'google':
            await upload_google()
        elif provider == 'google-vertex':
            await upload_google_vertex()
        elif provider == 'bedrock':
            await upload_bedrock_s3()
        else:
            print(f'  Unknown provider: {provider}')

